#
# @PLN91 — the generated bytecode runner against `loft --interpret` on the integer kernels:
# run_fill.loft built shipped, each kernel's call timed on both (answer, µs), and the ratio.
# A ratio is printed only where the two answers are equal.
#
#   selfhost/bench/fill_speed.sh [out dir]      (default: a scratch directory)
set -euo pipefail
if [ "${1:-}" = "--help" ]; then
  echo "usage: selfhost/bench/fill_speed.sh [out dir] — the generated bytecode runner against loft --interpret on the integer kernels"
  exit 0
fi
root=$(cd "$(dirname "$0")/../.." && pwd)
loft="$root/target/release/loft"
out=${1:-$(mktemp -d)}
mkdir -p "$out"
cd "$root/selfhost"
LOFT_NO_WARNINGS=1 "$loft" --native-c --ship --out "$out/rf" --lib src --lib crt/src bench/run_fill.loft >/dev/null
pin=(); command -v taskset >/dev/null && pin=(taskset -c 0)
for row in "fib n_fib 30" "mix n_mix 5000000 1" "collatz n_longest 1 100000"; do
  set -- $row; k=$1; f=$2; shift 2
  "$loft" --emit-image "$out/$k.store" "kernels/$k.loft" >/dev/null
  "$loft" --emit-run-image "$out/$k.run" "kernels/$k.loft" >/dev/null
  r=$("${pin[@]}" "$loft" --interpret "kernels/$k.loft" "$@" | tail -1)
  g=$("${pin[@]}" "$out/rf/run_fill" "$out/$k.store" "$out/$k.run" "$f" "$@" | tail -1)
  python3 - "$k" "$r" "$g" <<'PY'
import sys
k, r, g = sys.argv[1], sys.argv[2].split(), sys.argv[3].split()
same = len(r) > 1 and len(g) > 1 and r[0] == g[0]
print(f"{k}: loft --interpret {r[1] if len(r) > 1 else '?'} µs, generated runner {g[1] if len(g) > 1 else '?'} µs, "
      + (f"ratio {int(g[1]) / int(r[1]):.2f}" if same else f"ANSWERS DIFFER ({' '.join(r)} / {' '.join(g)})"))
sys.exit(0 if same else 1)
PY
done
